const packedCaveatMetricsModule = resolve(generatedDirectory, 'caveat-metrics028.js');
const packedCaveatInkModule = resolve(generatedDirectory, 'caveat-ink028.js');
const unpackHelper = `const _unp=(d,t,o,s,f,tp)=>{const ks=[];let p=0;for(const x of d)ks.push(String(p+=x));const out={};for(const [w,vs] of Object.entries(t)){const m={};for(let i=0;i<ks.length;i++)m[ks[i]]=tp?[Number((vs[i*2]/s).toFixed(f)),Number((vs[i*2+1]/s).toFixed(f))]:Number((vs[i]/s).toFixed(f));if(o[w])Object.assign(m,o[w]);out[w]=m;}return out;};\n`;
writeFileSync(packedCaveatMetricsModule, `/** GENERATED lossless browser packing of caveat-metrics028. */\n` +
  unpackHelper +
  `const _ca=_unp(${JSON.stringify(packCaveatMetrics.keyDeltas)},${JSON.stringify(packCaveatMetrics.tables)},${JSON.stringify(packCaveatMetrics.overrides)},1000,3,false);\n` +
  `export const CAVEAT_METRICS_028 = Object.fromEntries(Object.entries(${JSON.stringify(caveatMeta)}).map(([w,[unitsPerEm,ascent,descent,fallback]])=>[w,{unitsPerEm,ascent,descent,fallback,advances:_ca[w]}]));\n`);
writeFileSync(packedCaveatInkModule, `/** GENERATED lossless browser packing of caveat-ink028. */\n` +
  unpackHelper +
  `export const CAVEAT_INK_028 = _unp(${JSON.stringify(packCaveatInk.keyDeltas)},${JSON.stringify(packCaveatInk.tables)},${JSON.stringify(packCaveatInk.overrides)},1000,3,true);\n`);
// Verify exact lossless round-trip at build time.
const [{ GENERATED_FONT_ASSETS: rtSans }, { CAVEAT_METRICS_028: rtCm }, { CAVEAT_INK_028: rtCi }] = await Promise.all([
  import(pathToFileURL(reducedFontModule).href),
  import(pathToFileURL(packedCaveatMetricsModule).href),
  import(pathToFileURL(packedCaveatInkModule).href),
]);
if (JSON.stringify(rtSans.sans.metrics) !== JSON.stringify(sansMetrics)) throw new Error('Packed sans metrics diverged from source.');
if (JSON.stringify(rtCm) !== JSON.stringify(CAVEAT_METRICS_028)) throw new Error('Packed caveat metrics diverged from source.');
if (JSON.stringify(rtCi) !== JSON.stringify(CAVEAT_INK_028)) throw new Error('Packed caveat ink diverged from source.');

const successorBinding = createSuccessorBrowserBinding028(generatedDirectory);
const successorValidatorModule = successorBinding.validatorModule;

// Rolldown reports native ids; compare them with POSIX separators.
const posix = (id) => id?.replaceAll('\\', '/');
const AJV_STUB = '\0coral-browser:ajv-stub';
const SCHEMA_STUB = '\0coral-browser:schema-stub';
let elkRewritten = false;
let successorRewritten = false;
let caveatSourceRewritten = false;
let sansSourceRewritten = false;
const fontsModulePosix = posix(resolve(renderDist, 'text/fonts.js'));
const reducedFontModulePosix = posix(reducedFontModule);
const CAVEAT_SOURCE_RE = /\n\s*source:\s*\{\s*packageName:\s*'Caveat Latin variable'[\s\S]*?metricsSha256:\s*'generated-by-scripts\/generate-caveat-metrics028\.mjs',\s*\},/;
